# ============================================================================
# SP7001 XAPR plug-in (the Key Soft Service 'KSS' application resident in
# table flash). Program build 942 validates it with PlugInProbe and calls its
# header slots; see kn7000_sp7001_new.sym and notes/sp7001-build-diff.md.
# ============================================================================

# XaprHeader  (CPU 0x483E8000)
    .byte 0x58, 0x41, 0x50, 0x52   # 'XAPR' magic
    .long XaprFooter   # +0x04
    .long XapSlot08   # +0x08
    .long XapSlot0C   # +0x0C
    .long XapSlot10   # +0x10
    .long XapSlotDefault   # +0x14
    .long XapSlotDefault   # +0x18
    .long XapSlotDefault   # +0x1C
    .long XapSlotDefault   # +0x20
    .long XapSlotDefault   # +0x24
    .long XapSlotDefault   # +0x28
    .long XapSlotDefault   # +0x2C
    .long XapSlotDefault   # +0x30
    .long XapSlotDefault   # +0x34
    .long XapSlotDefault   # +0x38
# XapSlotDefault  (CPU 0x483E803C)
#   `rets`: the ten unused header slots +0x14..+0x38 point here
    rets
# func_483E803E  (CPU 0x483E803E)
    mov     0xa48, d1
    cmp     0, d1
    ble     0x483e8052
    mov     0x50299498, a0
    clr     d0
    mov     d0, (a0)
    inc4    a0
    add     -4, d1
    bgt     0x483e804c
    mov     0x1498, d1
    cmp     0, d1
    ble     0x483e806d
    mov     0x483fa104, a0
